<?php session_start();?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mijoz kabineti • Fast Food</title><style>body{margin:0;background:#f6f7fb;font-family:system-ui;color:#101828}.wrap{max-width:850px;margin:auto;padding:20px}.card{background:#fff;border:1px solid #e4e7ec;border-radius:22px;padding:22px;margin:14px 0;box-shadow:0 15px 40px #1018280c}input,button{width:100%;box-sizing:border-box;padding:12px;border-radius:12px;border:1px solid #ddd;margin:6px 0;font:inherit}button{background:#ff4d00;color:#fff;border:0;font-weight:800}.order{border:1px solid #eee;border-radius:16px;padding:15px;margin:10px 0}.muted{color:#667085}</style></head><body><div class="wrap"><div class="card"><h1>👤 Mijoz kabineti</h1><p class="muted">Kabinet ochmasdan ham buyurtma berishingiz mumkin. Kabinet ochsangiz buyurtma tarixingizni ko‘rasiz.</p><form id="f"><input name="phone" placeholder="Telefon raqamingiz" required><button>Kirish / Buyurtmalarim</button></form><div id="out"></div></div></div><script>f.onsubmit=async e=>{e.preventDefault();let p=new FormData(e.target).get('phone'),r=await fetch('customer_orders.php?phone='+encodeURIComponent(p)),d=await r.json();out.innerHTML=d.data?.length?d.data.map(x=>'<div class="order"><b>#'+x.id+'</b> — '+x.status+'<br>💰 '+Number(x.amount).toLocaleString('uz-UZ')+' so‘m<br>📍 '+(x.address||'')+'<br><small>'+new Date(x.created_at).toLocaleString('uz-UZ')+'</small></div>').join(''):'<p class="muted">Bu telefon uchun buyurtma topilmadi.</p>'}</script></body></html>